package ro.leo.visual;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;
/** Ephemeral credentials go only to the paired local harness; never publish raw instrumentation output. */
public final class CompanionLanTrial extends Instrumentation {
 public void onCreate(Bundle b){start();}public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();String fixture="leo-pc-trial-"+SystemClock.uptimeMillis()+".txt";boolean owned=false;try{if(CompanionService.instance!=null)throw new IllegalStateException("A companion session is already running");c.startForegroundService(new Intent(c,CompanionService.class));owned=true;for(int n=0;n<60&&CompanionService.instance==null;n++)SystemClock.sleep(100);CompanionService service=CompanionService.instance;if(service==null)throw new IOException("Wi-Fi session did not start");Bundle session=new Bundle();session.putString("endpoint",service.address);session.putString("token",service.secret);session.putString("fixture",fixture);sendStatus(1,session);SystemClock.sleep(20000);result.putString("result","Wi-Fi service session exercised and stopped");}catch(Throwable e){result.putString("error",e.getClass().getSimpleName());}finally{if(owned)c.stopService(new Intent(c,CompanionService.class));new File(CompanionServer.folder(c),fixture).delete();}finish(result.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}
